export const landingScript = (u: (p: string) => string, j: (v: unknown) => string, h: (v: unknown) => string): string => `<script>
(function () {
  // Reuses the EXISTING customers_search.php / orders_search.php endpoints — no new search
  // logic; results link straight to the EXISTING Customer/Order detail pages. The type picker
  // is now two radios instead of a <select>; everything downstream is unchanged.
  var input = document.getElementById('landingSearchInput');
  var box = document.getElementById('landingSearchResults');
  var help = document.getElementById('landingSearchHelp');
  var btn = document.getElementById('landingSearchBtn');
  var radios = document.querySelectorAll('input[name="landingSearchType"]');

  // Every value below comes from the database via the search API — a customer name, address or
  // code is arbitrary operator-entered text, so it must be treated as DATA, never as markup.
  // Without this, a customer saved as e.g. <img src=x onerror=...> would execute in the browser
  // of every staff member who searched for them (stored XSS). Escapes the five characters that
  // can break out of either an HTML text node or a quoted attribute value.
  function esc(v) {
    return String(v === null || v === undefined ? '' : v)
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&#39;');
  }

  var CONFIG = {
    customer: {
      url: ${j(u('api/customers_search.php'))},
      detailUrlBase: ${j(u('modules/customers/view.php?id='))},
      help: 'Search by Name, Address, Mobile, Customer Code or Barcode',
      placeholder: 'Search name, mobile, code, barcode...',
      render: function (r) {
        var addressParts = [r.address, r.area, r.city, r.state, r.pincode].filter(function (p) { return p && p.trim(); });
        var addressLine = addressParts.length ? addressParts.join(', ') : '';
        return '<div class="fw-bold">' + esc(r.full_name) + '</div>'
          + '<div class="text-muted">Mobile: ' + (r.mobile ? esc(r.mobile) : '—') + '</div>'
          + (addressLine ? '<div class="text-muted">Address: ' + esc(addressLine) + '</div>' : '')
          + (r.customer_code ? '<div class="text-muted">Customer Code: ' + esc(r.customer_code) + '</div>' : '');
      }
    },
    order: {
      url: ${j(u('api/orders_search.php'))},
      detailUrlBase: ${j(u('modules/orders/view.php?id='))},
      help: 'Search by Order Number or Invoice Number',
      placeholder: 'Search order number, invoice number...',
      render: function (r) { return '<strong>' + esc(r.short_order_code || r.order_number) + '</strong>' + (r.invoice_number ? ' / ' + esc(r.invoice_number) : '') + ' — ' + esc(r.customer_name); }
    }
  };

  function selectedType() {
    for (var i = 0; i < radios.length; i++) { if (radios[i].checked) return radios[i].value; }
    return 'customer';
  }
  function currentConfig() { return CONFIG[selectedType()]; }

  function updateHelpAndPlaceholder() {
    var c = currentConfig();
    help.textContent = c.help;
    input.placeholder = c.placeholder;
    box.classList.add('d-none');
    box.innerHTML = '';
  }
  for (var i = 0; i < radios.length; i++) {
    radios[i].addEventListener('change', updateHelpAndPlaceholder);
  }
  updateHelpAndPlaceholder();

  function runSearch() {
    var q = input.value.trim();
    if (q.length < 2) { box.classList.add('d-none'); return; }
    var c = currentConfig();
    fetch(c.url + '?q=' + encodeURIComponent(q))
      .then(function (r) { return r.json(); })
      .then(function (data) {
        var results = data.results || [];
        if (!results.length) {
          box.innerHTML = '<div class="list-group-item text-muted small">No matches.</div>';
          box.classList.remove('d-none');
          return;
        }
        box.innerHTML = results.map(function (r) {
          // r.id is escaped too — it lands inside a quoted attribute, where an unescaped quote
          // would let injected text break out and add its own event handler.
          return '<a href="' + c.detailUrlBase + esc(r.id) + '" class="list-group-item list-group-item-action small">' + c.render(r) + '</a>';
        }).join('');
        box.classList.remove('d-none');
      })
      .catch(function () { box.classList.add('d-none'); });
  }

  var timer = null;
  input.addEventListener('input', function () {
    clearTimeout(timer);
    timer = setTimeout(runSearch, 300);
  });
  input.addEventListener('keydown', function (e) { if (e.key === 'Enter') { e.preventDefault(); clearTimeout(timer); runSearch(); } });
  btn.addEventListener('click', function () { clearTimeout(timer); runSearch(); });
  document.addEventListener('click', function (e) {
    if (!box.contains(e.target) && e.target !== input) box.classList.add('d-none');
  });
})();
</script>`;
